import React, { useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";

const NavBar = ({ userRole, onLogout }) => {
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  const dropdownRef = useRef(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(e) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setIsDropdownOpen(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const closeMenus = () => {
    setIsMobileOpen(false);
    setIsDropdownOpen(false);
  };

  return (
    <nav className="bg-white shadow">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="flex h-16 items-center justify-between">
          {/* Brand */}
          <Link
            to="/"
            className="text-xl font-bold text-blue-600 hover:text-blue-800"
          >
            CampusConnect
          </Link>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center gap-6 text-gray-600">
            {userRole === "" && (
              <>
                <Link to="/home" className="hover:text-gray-900">
                  Home
                </Link>
                <Link to="/login" className="hover:text-gray-900">
                  Login
                </Link>
                <Link to="/register" className="hover:text-gray-900">
                  Register
                </Link>
              </>
            )}

            {/* STUDENT */}
            {userRole === "student" && (
              <>
                <Link to="/dashboard" className="hover:text-gray-900">
                  Dashboard
                </Link>

                <Link
                  to="/announcements-events"
                  className="hover:text-gray-900"
                >
                  Announcements
                </Link>

                {/* Dropdown */}
                <div className="relative" ref={dropdownRef}>
                  <button
                    onClick={() => setIsDropdownOpen((prev) => !prev)}
                    className="flex items-center gap-2 hover:text-gray-900"
                  >
                    Student Menu
                    <svg
                      className={`h-4 w-4 transition-transform ${
                        isDropdownOpen ? "rotate-180" : ""
                      }`}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M19 9l-7 7-7-7"
                      />
                    </svg>
                  </button>

                  {isDropdownOpen && (
                    <div className="absolute right-0 mt-3 w-56 overflow-hidden rounded-xl bg-white shadow-lg ring-1 ring-black/10">
                      <Link
                        to="/request-support"
                        onClick={closeMenus}
                        className="block px-4 py-3 text-gray-700 hover:bg-gray-50"
                      >
                        Request Support
                      </Link>

                      <Link
                        to="/feedback"
                        onClick={closeMenus}
                        className="block px-4 py-3 text-gray-700 hover:bg-gray-50"
                      >
                        Submit Feedback
                      </Link>

                      <button
                        onClick={() => {
                          closeMenus();
                          onLogout();
                        }}
                        className="w-full text-left px-4 py-3 text-red-600 hover:bg-gray-50"
                      >
                        Logout
                      </button>
                    </div>
                  )}
                </div>
              </>
            )}

            {/* ADMIN */}
            {userRole === "admin" && (
              <>
                <Link to="/admin-dashboard" className="hover:text-gray-900">
                  Dashboard
                </Link>

                {/* Dropdown */}
                <div className="relative" ref={dropdownRef}>
                  <button
                    onClick={() => setIsDropdownOpen((prev) => !prev)}
                    className="flex items-center gap-2 hover:text-gray-900"
                  >
                    Admin Menu
                    <svg
                      className={`h-4 w-4 transition-transform ${
                        isDropdownOpen ? "rotate-180" : ""
                      }`}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M19 9l-7 7-7-7"
                      />
                    </svg>
                  </button>

                  {isDropdownOpen && (
                    <div className="absolute right-0 mt-3 w-56 overflow-hidden rounded-xl bg-white shadow-lg ring-1 ring-black/10">
                      <Link
                        to="/admin-announcements"
                        onClick={closeMenus}
                        className="block px-4 py-3 text-gray-700 hover:bg-gray-50"
                      >
                        Post Announcements
                      </Link>

                      <Link
                        to="/admin-requests"
                        onClick={closeMenus}
                        className="block px-4 py-3 text-gray-700 hover:bg-gray-50"
                      >
                        View Requests
                      </Link>

                      <button
                        onClick={() => {
                          closeMenus();
                          onLogout();
                        }}
                        className="w-full text-left px-4 py-3 text-red-600 hover:bg-gray-50"
                      >
                        Logout
                      </button>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsMobileOpen((prev) => !prev)}
            className="md:hidden rounded-lg p-2 text-gray-700 hover:bg-gray-100"
          >
            {isMobileOpen ? (
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            ) : (
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M4 6h16M4 12h16M4 18h16"
                />
              </svg>
            )}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileOpen && (
        <div className="md:hidden border-t bg-white px-4 py-4 space-y-2 text-gray-700">
          {userRole === "" && (
            <>
              <Link to="/home" onClick={closeMenus} className="block py-2">
                Home
              </Link>
              <Link to="/login" onClick={closeMenus} className="block py-2">
                Login
              </Link>
              <Link to="/register" onClick={closeMenus} className="block py-2">
                Register
              </Link>
            </>
          )}

          {userRole === "student" && (
            <>
              <Link to="/dashboard" onClick={closeMenus} className="block py-2">
                Dashboard
              </Link>
              <Link
                to="/announcements-events"
                onClick={closeMenus}
                className="block py-2"
              >
                Announcements
              </Link>
              <Link
                to="/request-support"
                onClick={closeMenus}
                className="block py-2"
              >
                Request Support
              </Link>
              <Link to="/feedback" onClick={closeMenus} className="block py-2">
                Submit Feedback
              </Link>

              <button
                onClick={() => {
                  closeMenus();
                  onLogout();
                }}
                className="block py-2 text-red-600"
              >
                Logout
              </button>
            </>
          )}

          {userRole === "admin" && (
            <>
              <Link
                to="/admin-dashboard"
                onClick={closeMenus}
                className="block py-2"
              >
                Dashboard
              </Link>
              <Link
                to="/admin-announcements"
                onClick={closeMenus}
                className="block py-2"
              >
                Post Announcements
              </Link>
              <Link
                to="/admin-requests"
                onClick={closeMenus}
                className="block py-2"
              >
                View Requests
              </Link>

              <button
                onClick={() => {
                  closeMenus();
                  onLogout();
                }}
                className="block py-2 text-red-600"
              >
                Logout
              </button>
            </>
          )}
        </div>
      )}
    </nav>
  );
};

export default NavBar;
